import 'package:flutter/material.dart';

const _bg=Color(0xFF06131F),_surface=Color(0xFF102B3D),_teal=Color(0xFF18D6B0),_amber=Color(0xFFFFB547);
class LivePredictionScreen extends StatefulWidget{const LivePredictionScreen({super.key});@override State<LivePredictionScreen> createState()=>_LivePredictionScreenState();}
class _LivePredictionScreenState extends State<LivePredictionScreen>{
 final Map<String,String> picks={};final Set<String> locked={};final Map<String,bool> results={};int stage=0,xp=0,rewardChips=0;
 final questions=const [
  ('Powerplay Score','India score after 6 overs?',['0–39','40–49','50–59','60+'],'50–59',1),('Powerplay Wickets','India wickets after 6 overs?',['0','1','2','3+'],'1',1),('10 Over Score','India score after 10 overs?',['0–69','70–79','80–89','90+'],'80–89',2),('10 Over Wickets','India wickets after 10 overs?',['0–1','2','3','4+'],'2',2),('15 Over Score','India score after 15 overs?',['0–109','110–129','130–149','150+'],'130–149',3),('Final Score','India final innings score?',['0–159','160–179','180–199','200+'],'180–199',4),('Top Batter','Highest scorer for India?',['R. Sharma','S. Gill','S. Yadav','Other'],'S. Yadav',4),('Match Winner','Who wins the match?',['India','Australia'],'India',5),
 ];
 String get score=>switch(stage){0=>'48/1',1=>'56/1',2=>'84/2',3=>'137/3',4=>'188/6',_=>'188/6'};String get overs=>switch(stage){0=>'5.2 OV',1=>'6.0 OV',2=>'10.0 OV',3=>'15.0 OV',4=>'20.0 OV',_=>'20.0 OV'};String get progress=>switch(stage){0=>'Powerplay closes in 4 balls',1=>'Powerplay settled • 10-over predictions open',2=>'10-over checkpoint settled',3=>'15-over checkpoint settled',4=>'Innings complete • Match result pending',_=>'India won • Match settled'};
 void choose(String key,String value){if(locked.contains(key)){return;}setState(()=>picks[key]=value);}
 void advance(){if(stage>=5){return;}setState((){stage++;for(final q in questions){if(q.$6<=stage){locked.add(q.$1);if(picks.containsKey(q.$1)&&!results.containsKey(q.$1)){final ok=picks[q.$1]==q.$5;results[q.$1]=ok;if(ok){xp+=100;rewardChips+=25;}}}}});}
 void reset(){setState((){stage=0;xp=0;rewardChips=0;picks.clear();locked.clear();results.clear();});}
 @override Widget build(BuildContext context)=>Scaffold(backgroundColor:_bg,appBar:AppBar(title:const Text('Live Predictions'),actions:[Padding(padding:const EdgeInsets.only(right:14),child:Center(child:Text('$xp XP',style:const TextStyle(color:_amber,fontWeight:FontWeight.w900))))]),body:ListView(padding:const EdgeInsets.all(14),children:[
  Container(padding:const EdgeInsets.all(16),decoration:BoxDecoration(gradient:const LinearGradient(colors:[Color(0xFF073A3C),_surface]),borderRadius:BorderRadius.circular(18),border:Border.all(color:_teal.withValues(alpha:.35))),child:Column(children:[Row(children:[Container(width:8,height:8,decoration:BoxDecoration(color:stage<5?Colors.red:_teal,shape:BoxShape.circle)),const SizedBox(width:7),Text(stage<5?'LIVE • T20':'COMPLETED • T20',style:TextStyle(color:stage<5?Colors.redAccent:_teal,fontWeight:FontWeight.w900)),const Spacer(),const Text('SIMULATED FEED',style:TextStyle(fontSize:9,color:Colors.white54))]),const SizedBox(height:14),Row(children:[Expanded(child:_Team(name:'INDIA',score:score,overs:overs)),const Text('VS',style:TextStyle(color:Colors.white38,fontWeight:FontWeight.w900)),Expanded(child:_Team(name:'AUSTRALIA',score:stage<5?'Yet to bat':'176/8',overs:stage<5?'T20':'20.0 OV'))]),const Divider(height:24),Text(progress,textAlign:TextAlign.center,style:const TextStyle(color:_amber,fontWeight:FontWeight.w800)),const SizedBox(height:12),Row(children:[Expanded(child:FilledButton.icon(onPressed:stage<5?advance:null,icon:const Icon(Icons.skip_next),label:Text(stage<5?'ADVANCE DEMO':'SETTLED'))),const SizedBox(width:8),IconButton(onPressed:reset,tooltip:'Reset demo',icon:const Icon(Icons.restart_alt))])])),
  const SizedBox(height:12),Row(children:[Expanded(child:_Stat('PICKS','${picks.length}/8')),const SizedBox(width:7),Expanded(child:_Stat('CORRECT','${results.values.where((v)=>v).length}')),const SizedBox(width:7),Expanded(child:_Stat('XP','$xp')),const SizedBox(width:7),Expanded(child:_Stat('REWARD','+$rewardChips'))]),
  const SizedBox(height:16),const Text('PREDICTION LOBBY',style:TextStyle(fontSize:12,fontWeight:FontWeight.w900,color:_teal,letterSpacing:1)),const SizedBox(height:5),const Text('Choose before each checkpoint. Advance the demo to lock and settle predictions.',style:TextStyle(color:Colors.white60,fontSize:12)),const SizedBox(height:10),
  ...questions.map((q)=>_PredictionCard(title:q.$1,question:q.$2,options:q.$3,selected:picks[q.$1],locked:locked.contains(q.$1),result:results[q.$1],answer:locked.contains(q.$1)?q.$5:null,onSelect:(v)=>choose(q.$1,v))),
  const SizedBox(height:5),const Text('MATCH LEADERBOARD',style:TextStyle(fontSize:12,fontWeight:FontWeight.w900,color:_teal,letterSpacing:1)),const SizedBox(height:8),_Leader(rank:'1',name:'CricketKing',xp:'620 XP'),_Leader(rank:'2',name:'CoverDrive',xp:'480 XP'),_Leader(rank:'3',name:'YOU',xp:'$xp XP',you:true),const SizedBox(height:12),
  Container(padding:const EdgeInsets.all(14),decoration:BoxDecoration(color:_surface,borderRadius:BorderRadius.circular(14)),child:const Column(children:[Icon(Icons.verified_user_outlined,color:_teal),SizedBox(height:6),Text('FREE-PLAY SIMULATION',style:TextStyle(fontWeight:FontWeight.w900)),SizedBox(height:4),Text('100 XP + 25 virtual reward chips per correct demo prediction. No cash value, purchase, withdrawal or redemption. Production settlement will be server-authoritative.',textAlign:TextAlign.center,style:TextStyle(fontSize:10,color:Colors.white54))])),const SizedBox(height:18)
 ]));
}
class _Team extends StatelessWidget{final String name,score,overs;const _Team({required this.name,required this.score,required this.overs});@override Widget build(BuildContext context)=>Column(children:[Text(name,style:const TextStyle(fontWeight:FontWeight.w900)),const SizedBox(height:4),Text(score,style:const TextStyle(fontSize:22,fontWeight:FontWeight.w900,color:_amber)),Text(overs,style:const TextStyle(fontSize:9,color:Colors.white54))]);}
class _Stat extends StatelessWidget{final String label,value;const _Stat(this.label,this.value);@override Widget build(BuildContext context)=>Container(padding:const EdgeInsets.symmetric(vertical:10),decoration:BoxDecoration(color:_surface,borderRadius:BorderRadius.circular(10)),child:Column(children:[Text(value,style:const TextStyle(color:_amber,fontWeight:FontWeight.w900)),Text(label,style:const TextStyle(fontSize:8,color:Colors.white54))]));}
class _PredictionCard extends StatelessWidget{final String title,question;final List<String> options;final String? selected,answer;final bool locked;final bool? result;final ValueChanged<String> onSelect;const _PredictionCard({required this.title,required this.question,required this.options,required this.selected,required this.locked,required this.result,required this.answer,required this.onSelect});@override Widget build(BuildContext context){final border=result==true?_teal:result==false?Colors.redAccent:selected!=null?_amber:Colors.white10;return Container(margin:const EdgeInsets.only(bottom:10),padding:const EdgeInsets.all(14),decoration:BoxDecoration(color:_surface,borderRadius:BorderRadius.circular(14),border:Border.all(color:border.withValues(alpha:.55))),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[Expanded(child:Text(title.toUpperCase(),style:const TextStyle(fontSize:10,fontWeight:FontWeight.w900,color:_teal,letterSpacing:.8))),if(locked)const Icon(Icons.lock,size:15,color:Colors.white54),if(result!=null)...[const SizedBox(width:6),Icon(result!?Icons.check_circle:Icons.cancel,color:result!?_teal:Colors.redAccent,size:18)]]),const SizedBox(height:5),Text(question,style:const TextStyle(fontSize:16,fontWeight:FontWeight.w800)),const SizedBox(height:10),Wrap(spacing:7,runSpacing:7,children:options.map((o)=>ChoiceChip(label:Text(o),selected:selected==o,onSelected:locked?null:(_)=>onSelect(o),selectedColor:const Color(0xFF0B4B48),labelStyle:TextStyle(color:selected==o?_teal:Colors.white70,fontWeight:FontWeight.w700))).toList()),if(locked)...[const SizedBox(height:9),Text(selected==null?'Locked • No prediction submitted':'${result==true?'Correct':'Incorrect'} • Result: $answer',style:TextStyle(fontSize:10,color:result==true?_teal:result==false?Colors.redAccent:Colors.white54,fontWeight:FontWeight.w800))]]) ;}}
class _Leader extends StatelessWidget{final String rank,name,xp;final bool you;const _Leader({required this.rank,required this.name,required this.xp,this.you=false});@override Widget build(BuildContext context)=>Container(margin:const EdgeInsets.only(bottom:6),padding:const EdgeInsets.symmetric(horizontal:13,vertical:11),decoration:BoxDecoration(color:you?const Color(0xFF0B4B48):_surface,borderRadius:BorderRadius.circular(11),border:Border.all(color:you?_teal:Colors.white10)),child:Row(children:[CircleAvatar(radius:14,backgroundColor:you?_teal:Colors.white12,foregroundColor:you?_bg:Colors.white,child:Text(rank,style:const TextStyle(fontSize:10,fontWeight:FontWeight.w900))),const SizedBox(width:10),Expanded(child:Text(name,style:TextStyle(fontWeight:FontWeight.w800,color:you?_teal:Colors.white))),Text(xp,style:const TextStyle(color:_amber,fontWeight:FontWeight.w900))]));}
